sys_script_include.script:
var BudgetUtils = Class.create();
BudgetUtils.prototype = {
    initialize: function() {
        this._budgetTable = 'x_1610434_event_0_budget';
    },

    // calculateTotalBudget: function (_eventId) {
    //     var _budgetGR = new GlideRecordSecure(this._budgetTable);
    //     _budgetGR.addQuery('event_id', _eventId);
    //     _budgetGR.query();
    //     if (_budgetGR.next()) {
    //         return _budgetGR.getValue('total_budget');
    //     }
    //     return 0;
    // },
    calculateTotalBudget: function(_eventId) {
        var _totalBudget = 0;
        var _budgetGA = new GlideAggregate(this._budgetTable);
        _budgetGA.addQuery('event_id', _eventId);
        _budgetGA.addAggregate('SUM', 'total_budget');
        _budgetGA.query();
        if (_budgetGA.next()) {
            _totalBudget = _budgetGA.getAggregate('SUM', 'total_budget');
        }
        return _totalBudget;
    },

    calculateRemainingBudget: function(_eventId) {
        var _totalBudget = 0,
            _amountSpent = 0,
            _amountRemaining = 0;

        var _budgetGR = new GlideRecordSecure(this._budgetTable);
        _budgetGR.addQuery('event_id', _eventId);
        _budgetGR.query();

        if (_budgetGR.next()) {
            _totalBudget = parseFloat(_budgetGR.getValue('total_budget')) || 0;
            _amountSpent = parseFloat(_budgetGR.getValue('amount_spent')) || 0;
            _amountRemaining = _totalBudget - _amountSpent;
        }

        return _amountRemaining;
    },

    isBudgetApproved: function(_eventId) {
        var _budgetGR = new GlideRecordSecure(this._budgetTable);
        _budgetGR.addQuery('event_id', _eventId);
        _budgetGR.addQuery('status', 'approved');
        _budgetGR.query();
        return _budgetGR.hasNext();
    },

    getBudgetDetailsByEvent: function(_eventId) {
        var _budgetList = [];
        var _budgetGR = new GlideRecordSecure(this._budgetTable);
        _budgetGR.addQuery('event_id', _eventId);
        _budgetGR.query();
        while (_budgetGR.next()) {
            _budgetList.push(this._mapBudgetFields(_budgetGR));
        }
        return _budgetList;
    },

    _mapBudgetFields: function(_budgetGR) {
        return {
            sysId: _budgetGR.getUniqueValue(),
            eventId: _budgetGR.getValue('event_id'),
            totalBudget: _budgetGR.getValue('total_budget'),
            amountSpent: _budgetGR.getValue('amount_spent'),
            amountRemaining: _budgetGR.getValue('amount_remaining'),
            status: _budgetGR.getValue('status')
        };
    },
    type: 'BudgetUtils'
};
